// spec: specs/admin-business-package-label.md (1.1) · кейс: .qa/tests/admin-business-package-label/ADMIN-PKG-01.md
// seed: tests/seed.admin.spec.ts · ПРОД: только просмотр, кнопки строк и «רענן רשימה» не нажимаются.
// Не-GET блокируются, кроме чтения прав rpc/is_admin (POST-RPC без записи).
import { test, expect } from '@playwright/test';

const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
const READ_ONLY_RPC = /\/rest\/v1\/rpc\/is_admin$/;
const LOAD = { timeout: 20_000 };

test.use({ storageState: '../auth/admin.json', serviceWorkers: 'block' });

test('«ניהול עסקים»: бесплатный пакет — «חבילה בחינם» / «חינם», «ללא חבילה» только у черновиков #f67768 @desktop @prod-safe', async ({ page }) => {
  await page.route('**/*', (route) => {
    const r = route.request();
    if (SAFE_METHODS.includes(r.method()) || READ_ONLY_RPC.test(r.url().split('?')[0])) return route.fallback();
    return route.abort('blockedbyclient');
  });

  await page.goto('/admin');
  await expect(page.getByRole('heading', { name: 'ניהול - פאנל מנהל' })).toBeVisible(LOAD);
  const tab = page.getByRole('tab', { name: /ניהול עסקים/ });
  await tab.click();
  await expect(tab).toHaveAttribute('aria-selected', 'true');
  await expect(page.getByRole('heading', { name: 'ניהול עסקים' })).toBeVisible(LOAD);

  // Фильтр статуса (по умолчанию «בהמתנה») → «הכל».
  await page.getByRole('combobox').first().click();
  await page.getByRole('option', { name: 'הכל', exact: true }).click();
  await expect(page.getByRole('combobox').first()).toContainText('הכל');

  const rows = page.locator('table tbody tr');
  // В «הכל» на проде 400+ строк (04.11: 412); в «בהמתנה» — единицы. Ждём полный список.
  await expect.poll(() => rows.count(), { message: 'список «הכל» загрузился', ...LOAD }).toBeGreaterThan(20);

  const headers = (await page.locator('table th').allInnerTexts()).map((h) => h.trim());
  const iName = headers.indexOf('שם העסק');
  const iPkg = headers.indexOf('חבילה');
  const iPay = headers.indexOf('תשלום');
  expect(iPkg, 'колонка «חבילה»').toBeGreaterThanOrEqual(0);
  expect(iPay, 'колонка «תשלום»').toBeGreaterThanOrEqual(0);

  const data = await rows.evaluateAll((trs, idx) =>
    trs.map((tr) => {
      const td = Array.from(tr.querySelectorAll('td')).map((c) => (c as HTMLElement).innerText.trim().replace(/\s+/g, ' '));
      return { name: td[idx.iName] ?? '', pkg: td[idx.iPkg] ?? '', pay: td[idx.iPay] ?? '' };
    }), { iName, iPkg, iPay });

  const free = data.filter((d) => d.pkg === 'חבילה בחינם');
  expect(free.length, 'есть строки «חבילה בחינם»').toBeGreaterThan(0);
  expect(free.filter((d) => d.pay !== 'חינם').map((d) => `${d.name}: ${d.pay}`), '«חבילה בחינם» → «תשלום» = «חינם»').toEqual([]);

  // «ללא חבילה» / «—» — только у черновиков (бейдж «טיוטה» в ячейке названия).
  const noPkg = data.filter((d) => d.pkg === '—' || d.pkg === '' || /ללא חבילה/.test(d.pkg) || /ללא חבילה/.test(d.pay));
  expect(noPkg.filter((d) => !/טיוטה/.test(d.name)).map((d) => `${d.name}: ${d.pkg} / ${d.pay}`), '«ללא חבילה» только у «טיוטה»').toEqual([]);

  // Платные — «חבילה 2/3 … עד <дата>» / «שולם».
  const paid = data.filter((d) => /^חבילה [23]/.test(d.pkg));
  expect(paid.filter((d) => !/עד \d{1,2}\.\d{1,2}\.\d{4}/.test(d.pkg) || d.pay !== 'שולם').map((d) => `${d.name}: ${d.pkg} / ${d.pay}`), 'платные: «עד <дата>» / «שולם»').toEqual([]);
});
